WITH base AS (SELECT *, CEIL(rating) AS rating_whole, COALESCE(city, 'UNKNOWN') AS city_clean FROM suppliers WHERE city IS NOT NULL), metrics AS (SELECT *, RANK() OVER w_hist AS rating_rank, LAST_VALUE(rating_whole, TRUE) OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_rating_whole, ROW_NUMBER() OVER (PARTITION BY country ORDER BY rating_whole DESC, id) AS row_seq FROM base WHERE supplier_name LIKE '%City%' WINDOW w_hist AS (PARTITION BY country, city ORDER BY rating)), remaining_keys AS (SELECT city, id FROM metrics INTERSECT ALL SELECT city, id FROM suppliers WHERE rating BETWEEN 1.8 AND 2.2), reconciled AS (SELECT s.* FROM metrics s INNER JOIN remaining_keys k ON s.city = k.city AND s.id = k.id), scored AS (SELECT id, supplier_name, rating, rating_rank, row_seq, DENSE_RANK() OVER (PARTITION BY country ORDER BY row_seq DESC) AS row_seq_dense_rank, COUNT(rating) OVER (PARTITION BY country) AS country_count_rating, SUM(last_known_rating_whole) OVER (PARTITION BY city) AS city_sum_last_known_rating_whole, DENSE_RANK() OVER (PARTITION BY country, city ORDER BY rating_whole DESC NULLS LAST) AS rating_whole_dense_rank, MIN(rating_rank) OVER (PARTITION BY city) AS city_min_rating_rank FROM reconciled) SELECT CASE WHEN city_min_rating_rank >= 8 THEN 'LARGE' ELSE 'SMALL' END AS city_min_rating_rank_tier, CASE WHEN country_count_rating >= 14 THEN 'HIGH' ELSE 'LOW' END AS country_count_rating_tier, COUNT(DISTINCT id) AS distinct_ids, SUM(country_count_rating) AS total_country_count_rating, APPROX_PERCENTILE(city_sum_last_known_rating_whole, ARRAY(0.25, 0.5, 0.75)) AS city_sum_last_known_rating_whole_quartiles, SUM(row_seq_dense_rank) AS total_row_seq_dense_rank FROM scored GROUP BY CASE WHEN city_min_rating_rank >= 8 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN country_count_rating >= 14 THEN 'HIGH' ELSE 'LOW' END HAVING total_row_seq_dense_rank >= 0 ORDER BY country_count_rating_tier DESC;
